import React, { useMemo, useState } from 'react';
import {
  Chip,
  ChipGroup,
  Card,
  CardBody,
  Stack,
  Inline,
  Text,
  ProgressCircle,
  Badge,
  Pagination,
  EmptyState,
  Button,
} from '@jinx-ui/react';

type ProjectStatus = 'active' | 'paused' | 'over-quota' | 'completed';

interface Project {
  id: string;
  name: string;
  quotaUsedPercent: number;
  status: ProjectStatus;
}

const PROJECTS: Project[] = [
  { id: 'p1', name: 'Атлас', quotaUsedPercent: 42, status: 'active' },
  { id: 'p2', name: 'Орион', quotaUsedPercent: 98, status: 'over-quota' },
  { id: 'p3', name: 'Вектор', quotaUsedPercent: 15, status: 'paused' },
  { id: 'p4', name: 'Меридиан', quotaUsedPercent: 100, status: 'completed' },
  { id: 'p5', name: 'Кристалл', quotaUsedPercent: 67, status: 'active' },
  { id: 'p6', name: 'Гелиос', quotaUsedPercent: 30, status: 'paused' },
  { id: 'p7', name: 'Немо', quotaUsedPercent: 12, status: 'active' },
  { id: 'p8', name: 'Титан', quotaUsedPercent: 110, status: 'over-quota' },
  { id: 'p9', name: 'Ирис', quotaUsedPercent: 55, status: 'active' },
  { id: 'p10', name: 'Аврора', quotaUsedPercent: 100, status: 'completed' },
  { id: 'p11', name: 'Феникс', quotaUsedPercent: 8, status: 'paused' },
  { id: 'p12', name: 'Нептун', quotaUsedPercent: 73, status: 'active' },
];

const STATUS_META: Record<
  ProjectStatus,
  { label: string; tone: 'success' | 'warning' | 'danger' | 'neutral' }
> = {
  active: { label: 'Активен', tone: 'success' },
  paused: { label: 'На паузе', tone: 'neutral' },
  'over-quota': { label: 'Превышение квоты', tone: 'danger' },
  completed: { label: 'Завершён', tone: 'warning' },
};

const PAGE_SIZE = 5;

export default function ProjectQuotaPanel() {
  const [activeStatuses, setActiveStatuses] = useState<ProjectStatus[]>([]);
  const [page, setPage] = useState(1);

  const toggleStatus = (status: ProjectStatus) => {
    setActiveStatuses((prev) =>
      prev.includes(status) ? prev.filter((s) => s !== status) : [...prev, status]
    );
    setPage(1);
  };

  const resetFilters = () => {
    setActiveStatuses([]);
    setPage(1);
  };

  const filteredProjects = useMemo(() => {
    if (activeStatuses.length === 0) return PROJECTS;
    return PROJECTS.filter((p) => activeStatuses.includes(p.status));
  }, [activeStatuses]);

  const pageCount = Math.max(1, Math.ceil(filteredProjects.length / PAGE_SIZE));
  const currentPage = Math.min(page, pageCount);

  const pageItems = useMemo(() => {
    const start = (currentPage - 1) * PAGE_SIZE;
    return filteredProjects.slice(start, start + PAGE_SIZE);
  }, [filteredProjects, currentPage]);

  const allStatuses = Object.keys(STATUS_META) as ProjectStatus[];

  return (
    <Card className="jx-p-4">
      <CardBody>
        <Stack gap="4">
          <Stack gap="2">
            <Text size="sm" tone="secondary">
              Фильтр по статусу
            </Text>
            <ChipGroup>
              {allStatuses.map((status) => {
                const meta = STATUS_META[status];
                const selected = activeStatuses.includes(status);
                return (
                  <Chip
                    key={status}
                    selected={selected}
                    onClick={() => toggleStatus(status)}
                    onRemove={selected ? () => toggleStatus(status) : undefined}
                    removable={selected}
                    tone={meta.tone}
                  >
                    {meta.label}
                  </Chip>
                );
              })}
            </ChipGroup>
          </Stack>

          {pageItems.length === 0 ? (
            <EmptyState
              title="Ничего не найдено"
              description="Под выбранные фильтры не попал ни один проект."
              action={
                <Button variant="secondary" onClick={resetFilters}>
                  Сбросить фильтры
                </Button>
              }
            />
          ) : (
            <Stack gap="0" style={{ borderTop: '1px solid var(--jx-color-border-subtle)' }}>
              {pageItems.map((project) => {
                const meta = STATUS_META[project.status];
                return (
                  <Inline
                    key={project.id}
                    align="center"
                    justify="between"
                    gap="4"
                    className="jx-py-3"
                    style={{ borderBottom: '1px solid var(--jx-color-border-subtle)' }}
                  >
                    <Text weight="medium">{project.name}</Text>
                    <Inline align="center" gap="3">
                      <ProgressCircle
                        value={Math.min(project.quotaUsedPercent, 100)}
                        size="sm"
                        tone={meta.tone}
                        label={`${project.quotaUsedPercent}%`}
                      />
                      <Badge tone={meta.tone}>{meta.label}</Badge>
                    </Inline>
                  </Inline>
                );
              })}
            </Stack>
          )}

          {pageItems.length > 0 && pageCount > 1 && (
            <Pagination
              page={currentPage}
              pageCount={pageCount}
              onPageChange={setPage}
            />
          )}
        </Stack>
      </CardBody>
    </Card>
  );
}

